/* SSSE3, SSE4.1, SSE4.2 and PCLMULQDQ against the hardware: every
 * instruction over pseudo-random inputs (NaN, infinities, signed zeros,
 * text-like strings among them) and every immediate that changes what it
 * computes, each group's results hashed (FNV-1a) and checked against the
 * hashes a real x86-64 CPU gave (the table at the end; regenerate it with
 * "sse4 --print" on one). Prints "sse4 ok", or a line per group that
 * differs. With an argument "NAME,...", only those groups. x86-64 only. */
#ifdef __clang__
#pragma clang attribute push (__attribute__((target("ssse3,sse4.1,sse4.2,crc32,pclmul,popcnt"))), apply_to = function)
#else
#pragma GCC target("ssse3,sse4.1,sse4.2,pclmul,popcnt")
#endif
