static uint64_t h, rs;
static uint64_t rnd(void) { rs ^= rs << 13; rs ^= rs >> 7; rs ^= rs << 17; return rs; }
static __attribute__((noinline)) void mix(const void *p, int n) { const unsigned char *c = p; for (int i = 0; i < n; i++) { h ^= c[i]; h *= 0x100000001b3ull; } }
static void mixv(__m128i v) { mix(&v, 16); }
static void mixf(__m128 v) { mix(&v, 16); }
static void mixd(__m128d v) { mix(&v, 16); }
static void mixi(long long x) { mix(&x, 8); }
static __m128i ri(void)
{
    uint64_t a = rnd(), b = rnd();
    int k = rnd() % 8;
    if (k == 0) a &= 0x00ff00ff00ff00ffull;
    if (k == 1) a = ~0ull;
    if (k == 2) b = 0;
    if (k == 3) a |= 0x8080808080808080ull;
    if (k == 4) { a = 0x6463626144434241ull ^ (rnd() & 0x0101010101010101ull); b = (rnd() & 1) ? 0 : 0x0068676665ull; }
    return _mm_set_epi64x((long long)b, (long long)a);
}
static float sf(void)
{
    static const float sp[] = { 0.0f, -0.0f, 0.5f, -0.5f, 1.5f, 2.5f, -2.5f, 1e30f, -1e-30f, INFINITY, -INFINITY, NAN, 3.49999f, -7.5f, 8388609.0f, 0.49999997f };
    uint64_t r = rnd();
    if (r % 3 == 0) return sp[(r >> 8) % 16];
    uint32_t u = (uint32_t)(r >> 16);
    float f;
    if (r % 3 == 1) return (float)((int32_t)u % 20000) / 8.0f;
    memcpy(&f, &u, 4);
    return f;
}
static double sd(void)
{
    static const double sp[] = { 0.0, -0.0, 0.5, -0.5, 1.5, 2.5, -2.5, 1e300, -1e-300, INFINITY, -INFINITY, NAN, 3.4999999, -7.5, 4503599627370497.0, 0.49999999999999994 };
    uint64_t r = rnd();
    if (r % 3 == 0) return sp[(r >> 8) % 16];
    if (r % 3 == 1) return (double)((int64_t)(r >> 16) % 200000) / 16.0;
    double d;
    uint64_t u = rnd();
    memcpy(&d, &u, 8);
    return d;
}
/* finite values whose products and sums are exact or tame */
static float tf(void) { return (float)((int)(rnd() % 41) - 20) * 0.25f; }
static double td(void) { return (double)((int)(rnd() % 41) - 20) * 0.25; }
/* (one call per statement: the order of a call's arguments is unspecified) */
static __m128 rf(void) { float a = sf(), b = sf(), c = sf(), d = sf(); return _mm_set_ps(a, b, c, d); }
static __m128d rd(void) { double a = sd(), b = sd(); return _mm_set_pd(a, b); }
static __m128 tfv(void) { float a = tf(), b = tf(), c = tf(), d = tf(); return _mm_set_ps(a, b, c, d); }
static __m128d tdv(void) { double a = td(), b = td(); return _mm_set_pd(a, b); }

