int main(int argc, char **argv)
{
    int print = argc > 1 && !strcmp(argv[1], "--print"), bad = 0;
    const char *only = argc > 1 && !print ? argv[1] : NULL;
    for (unsigned k = 0; k < sizeof(groups) / sizeof(groups[0]); k++) {
        char key[64];
        snprintf(key, sizeof(key), "%s,", groups[k].name);
        if (only && !strstr(only, key)) continue;
        h = 0xcbf29ce484222325ull;
        rs = 0x9e3779b97f4a7c15ull;
        groups[k].run();
        if (print) printf("%s %016llx\n", groups[k].name, (unsigned long long)h);
        else if (h != groups[k].want) {
            printf("sse4 %s: %016llx, the hardware's %016llx\n", groups[k].name, (unsigned long long)h, (unsigned long long)groups[k].want);
            bad = 1;
        }
    }
    if (!print && !bad) printf("sse4 ok\n");
    return bad;
}
